-- +goose Up

-- Conventions
--   * Primary keys are UUIDs generated by the application (UUIDv7), so there is
--     no DEFAULT here. Exception: `unit` uses a short natural key (its code) so
--     seed data and ingredient rows stay readable.
--   * "Enums" are text + CHECK constraints rather than Postgres ENUM types, which
--     are painful to alter.
--   * created_by columns are deliberately absent for now (no auth); add when users exist.

-- ---------------------------------------------------------------------------
-- updated_at maintenance
-- ---------------------------------------------------------------------------
-- +goose StatementBegin
CREATE FUNCTION set_updated_at() RETURNS trigger AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
-- +goose StatementEnd

-- ---------------------------------------------------------------------------
-- Reference data: units
-- ---------------------------------------------------------------------------
-- base_factor converts to the dimension's base unit: millilitres for volume,
-- grams for mass. Count units never convert (NULL).
CREATE TABLE unit (
    code        text PRIMARY KEY,
    name        text NOT NULL,
    dimension   text NOT NULL CHECK (dimension IN ('volume', 'mass', 'count')),
    base_factor numeric(18, 6) CHECK (base_factor > 0),
    CHECK ((dimension = 'count') = (base_factor IS NULL))
);

