-- ---------------------------------------------------------------------------
-- Reference data: food categories
-- ---------------------------------------------------------------------------
-- A store-independent grouping ("produce", "baking"). Where a category lives
-- in a particular store (aisle, walking order) is per-store data that arrives
-- with the store tables; `position` is only the default order when no store is
-- selected.
CREATE TABLE food_category (
    code     text PRIMARY KEY,
    name     text NOT NULL,
    position integer NOT NULL UNIQUE
);

