    ('frozen',     'Frozen',               150),
    ('household',  'Household',            160);

-- ---------------------------------------------------------------------------
-- Foods: the canonical identity of an ingredient
-- ---------------------------------------------------------------------------
-- "all-purpose flour" is one food no matter how a recipe spells it. Shopping
-- lists, pantry tracking and "what can I make" all hang off this table.
CREATE TABLE food (
    id               uuid PRIMARY KEY,
    name             text NOT NULL CHECK (btrim(name) <> ''),
    category_code    text REFERENCES food_category (code),
    is_staple        boolean NOT NULL DEFAULT false,  -- assumed on hand (salt, oil)
    shelf_life_days  integer CHECK (shelf_life_days > 0),
    default_location text CHECK (default_location IN ('pantry', 'fridge', 'freezer', 'other')),
    created_at       timestamptz NOT NULL DEFAULT now(),
    updated_at       timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX food_name_key ON food (lower(name));
CREATE TRIGGER food_set_updated_at BEFORE UPDATE ON food
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- Alternative spellings that resolve to a food ("plain flour" -> all-purpose flour).
-- Uniqueness across names and aliases together is enforced by the application.
CREATE TABLE food_alias (
    food_id uuid NOT NULL REFERENCES food (id) ON DELETE CASCADE,
    alias   text NOT NULL CHECK (btrim(alias) <> ''),
    PRIMARY KEY (food_id, alias)
);
CREATE UNIQUE INDEX food_alias_key ON food_alias (lower(alias));

-- ---------------------------------------------------------------------------
-- Media (images). Bytes live in a storage backend; this row is the pointer.
-- ---------------------------------------------------------------------------
CREATE TABLE media (
    id           uuid PRIMARY KEY,
    storage_key  text NOT NULL UNIQUE,
    content_type text NOT NULL,
    size_bytes   bigint CHECK (size_bytes >= 0),
    width        integer CHECK (width > 0),
    height       integer CHECK (height > 0),
    created_at   timestamptz NOT NULL DEFAULT now()
);

-- ---------------------------------------------------------------------------
-- Recipes
-- ---------------------------------------------------------------------------
CREATE TABLE recipe (
    id           uuid PRIMARY KEY,
    title        text NOT NULL CHECK (btrim(title) <> ''),
    description  text NOT NULL DEFAULT '',
    servings     numeric(8, 2) CHECK (servings > 0),
    yield_text   text,                     -- "12 cookies", when servings does not fit
    prep_minutes integer CHECK (prep_minutes >= 0),
    cook_minutes integer CHECK (cook_minutes >= 0),
    source_url   text,
    source_name  text,
    source_data  jsonb,                    -- raw imported payload (e.g. schema.org JSON-LD)
    notes        text NOT NULL DEFAULT '',
    is_favorite  boolean NOT NULL DEFAULT false,
    image_id     uuid REFERENCES media (id) ON DELETE SET NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    updated_at   timestamptz NOT NULL DEFAULT now(),
    search       tsvector GENERATED ALWAYS AS (
                     to_tsvector('english', title || ' ' || description)
                 ) STORED
);
CREATE INDEX recipe_search_idx ON recipe USING gin (search);
CREATE INDEX recipe_source_url_idx ON recipe (source_url) WHERE source_url IS NOT NULL;
CREATE TRIGGER recipe_set_updated_at BEFORE UPDATE ON recipe
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- One line of a recipe's ingredient list.
-- Keeps the original text (raw_text) alongside the parsed fields, so a parse
-- mistake never loses information and the parser can be improved later.
CREATE TABLE ingredient (
    id            uuid PRIMARY KEY,
    recipe_id     uuid NOT NULL REFERENCES recipe (id) ON DELETE CASCADE,
    position      integer NOT NULL CHECK (position >= 0),
    section       text,                    -- "For the sauce"
    raw_text      text NOT NULL,
    quantity_min  numeric(10, 4) CHECK (quantity_min >= 0),
    quantity_max  numeric(10, 4),          -- set for ranges ("2-3 cloves")
    unit_code     text REFERENCES unit (code),
    food_id       uuid REFERENCES food (id),            -- NULL until matched
    name          text NOT NULL CHECK (btrim(name) <> ''),  -- display name as written
    preparation   text,                    -- "finely diced"
    note          text,
    optional      boolean NOT NULL DEFAULT false,
    sub_recipe_id uuid REFERENCES recipe (id),          -- e.g. "pizza dough" in "pizza"
    CHECK (quantity_max IS NULL OR (quantity_min IS NOT NULL AND quantity_max >= quantity_min)),
    CHECK (sub_recipe_id IS NULL OR sub_recipe_id <> recipe_id),
    -- Deferred so positions can be rewritten inside one transaction when reordering.
    UNIQUE (recipe_id, position) DEFERRABLE INITIALLY DEFERRED
);
CREATE INDEX ingredient_food_idx ON ingredient (food_id) WHERE food_id IS NOT NULL;
CREATE INDEX ingredient_sub_recipe_idx ON ingredient (sub_recipe_id) WHERE sub_recipe_id IS NOT NULL;

CREATE TABLE step (
    id            uuid PRIMARY KEY,
    recipe_id     uuid NOT NULL REFERENCES recipe (id) ON DELETE CASCADE,
    position      integer NOT NULL CHECK (position >= 0),
    section       text,
    instruction   text NOT NULL CHECK (btrim(instruction) <> ''),
    timer_seconds integer CHECK (timer_seconds > 0),   -- for cooking-mode timers
    UNIQUE (recipe_id, position) DEFERRABLE INITIALLY DEFERRED
);

-- ---------------------------------------------------------------------------
-- Tags
-- ---------------------------------------------------------------------------
CREATE TABLE tag (
    id   uuid PRIMARY KEY,
    name text NOT NULL CHECK (btrim(name) <> ''),
    kind text NOT NULL DEFAULT 'other'
         CHECK (kind IN ('cuisine', 'course', 'diet', 'occasion', 'other'))
);
CREATE UNIQUE INDEX tag_kind_name_key ON tag (kind, lower(name));

CREATE TABLE recipe_tag (
    recipe_id uuid NOT NULL REFERENCES recipe (id) ON DELETE CASCADE,
    tag_id    uuid NOT NULL REFERENCES tag (id) ON DELETE CASCADE,
    PRIMARY KEY (recipe_id, tag_id)
);
CREATE INDEX recipe_tag_tag_idx ON recipe_tag (tag_id);

-- ---------------------------------------------------------------------------
-- Tools and equipment
-- ---------------------------------------------------------------------------
CREATE TABLE tool (
    id         uuid PRIMARY KEY,
    name       text NOT NULL CHECK (btrim(name) <> ''),
    category   text NOT NULL DEFAULT 'other'
               CHECK (category IN ('appliance', 'cookware', 'bakeware', 'utensil', 'other')),
    owned      boolean NOT NULL DEFAULT false,   -- one household, so a plain flag
    notes      text NOT NULL DEFAULT '',
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX tool_name_key ON tool (lower(name));
CREATE TRIGGER tool_set_updated_at BEFORE UPDATE ON tool
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE tool_alias (
    tool_id uuid NOT NULL REFERENCES tool (id) ON DELETE CASCADE,
    alias   text NOT NULL CHECK (btrim(alias) <> ''),
    PRIMARY KEY (tool_id, alias)
);
CREATE UNIQUE INDEX tool_alias_key ON tool_alias (lower(alias));

CREATE TABLE recipe_tool (
    recipe_id uuid NOT NULL REFERENCES recipe (id) ON DELETE CASCADE,
    tool_id   uuid NOT NULL REFERENCES tool (id),
    spec      text,                              -- "9x13 inch", "large"
    optional  boolean NOT NULL DEFAULT false,
    PRIMARY KEY (recipe_id, tool_id)
);
CREATE INDEX recipe_tool_tool_idx ON recipe_tool (tool_id);

-- ---------------------------------------------------------------------------
-- Pantry: what is on hand
-- ---------------------------------------------------------------------------
-- One row per purchase/lot; food_id is intentionally NOT unique (two jars of
-- jam with different expiry dates are two rows). A food is available if any of
-- its rows is in stock, or if the food is a staple.
-- Availability (status) is the primary signal; quantity is optional because
-- keeping precise counts rarely survives in practice.
CREATE TABLE pantry_item (
    id           uuid PRIMARY KEY,
    food_id      uuid NOT NULL REFERENCES food (id),
    status       text NOT NULL DEFAULT 'in_stock' CHECK (status IN ('in_stock', 'low', 'out')),
    quantity     numeric(10, 3) CHECK (quantity >= 0),
    unit_code    text REFERENCES unit (code),
    location     text CHECK (location IN ('pantry', 'fridge', 'freezer', 'other')),
    purchased_on date,
    opened_on    date,
    expires_on   date,
    notes        text NOT NULL DEFAULT '',
    created_at   timestamptz NOT NULL DEFAULT now(),
    updated_at   timestamptz NOT NULL DEFAULT now(),
    CHECK (quantity IS NULL OR unit_code IS NOT NULL)
);
CREATE INDEX pantry_item_food_idx ON pantry_item (food_id);
CREATE INDEX pantry_item_expires_idx ON pantry_item (expires_on) WHERE expires_on IS NOT NULL;
CREATE TRIGGER pantry_item_set_updated_at BEFORE UPDATE ON pantry_item
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- +goose Down
DROP TABLE pantry_item;
DROP TABLE recipe_tool;
DROP TABLE tool_alias;
DROP TABLE tool;
DROP TABLE recipe_tag;
DROP TABLE tag;
DROP TABLE step;
DROP TABLE ingredient;
DROP TABLE recipe;
DROP TABLE media;
DROP TABLE food_alias;
DROP TABLE food;
DROP TABLE food_category;
DROP TABLE unit;
DROP FUNCTION set_updated_at();
